      <td>${nlpScore}/100</td>
      <td><div class="bar-container"><div class="bar-fill" style="width:${nlpScore}%"></div></div></td>
    </tr>
    <tr>
      <td>Modèle 4 — Vision photos</td>
      <td>20%</td>
      <td>${visionScore}/100</td>
      <td><div class="bar-container"><div class="bar-fill" style="width:${visionScore}%"></div></div></td>
    </tr>
  </table>

