  <div class="section-title">3. Décision Finale</div>
  <div class="decision-box">
    <div class="decision-outcome">DÉCISION : APPROUVÉ</div>
    <div class="decision-comment"><strong>Commentaire de l'investigateur :</strong></div>
    <div class="decision-comment">${notes}</div>
    <div class="decision-date">Décision prise le ${decidedAt}</div>
  </div>

  <!-- FOOTER -->
  <div class="footer">
    <div>TAAMINE — Industrial Insurance Fraud Detection — Document confidentiel</div>
    <div class="page-num">Page 1 / 1</div>
  </div>

</body>
</html>
